// Extract incoming investigation summary from ThreatWeave
const input = $input.first().json;
const payload = input.body || input;

const formattedIncident = {
  status: "alert_dispatched",
  investigation_id: payload.investigation_id || "unknown",
  title: payload.title || "Untitled Incident",
  final_severity: (payload.final_severity || "UNKNOWN").toUpperCase(),
  final_risk_score: payload.final_risk_score !== undefined ? payload.final_risk_score : null,
  top_indicators: payload.top_indicators || [],
  received_at: new Date().toISOString(),
  alert_summary: `[THREATWEAVE ALERT] ${payload.title || 'Incident'} (${(payload.final_severity || 'UNKNOWN').toUpperCase()} - Score: ${payload.final_risk_score}) triggered. Detected indicators: ${(payload.top_indicators || []).join(', ') || 'None'}`
};

return [{ json: formattedIncident }];
